from typing import Dict

class Warehouse:
    def __init__(self, stock: Dict[str, int]):
        self.stock = dict(stock)

    def available(self, sku: str) -> int:
        return self.stock.get(sku, 0)

    def deduct(self, sku: str, qty: int) -> bool:
        if self.available(sku) < qty:
            return False
        self.stock[sku] -= qty
        return True

